"use client";

import Image from "next/image";
import { useLayoutEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { MotionPathPlugin } from "gsap/MotionPathPlugin";

gsap.registerPlugin(ScrollTrigger, MotionPathPlugin);

export default function TransferCard() {
  const section = useRef<HTMLElement>(null);
  const background = useRef<HTMLDivElement>(null);
  const card = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      gsap.set(card.current, {
        transformPerspective: 1200,
        transformOrigin: "center center",
      });

      // Floating effect
      const floating = gsap.to(card.current, {
        y: "+=8",
        duration: 1.8,
        repeat: -1,
        yoyo: true,
        ease: "sine.inOut",
      });

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: section.current,
          start: "top top",
          end: "+=2200",
          scrub: 1,
          pin: true,
          anticipatePin: 1,
        },
      });

      tl.add(() => floating.pause())

        // Background zoom
        .to(
          background.current,
          {
            scale: 1.12,
            ease: "none",
            duration: 4,
          },
          0
        )

        // Card movement
        .to(
          card.current,
          {
            motionPath: {
              path: [
                { x: 0, y: 0 },
                { x: 180, y: -110 },
                { x: 420, y: -60 },
                { x: 650, y: 15 },
              ],
              curviness: 1.8,
            },
            rotateZ: 18,
            rotateX: 8,
            rotateY: 18,
            scale: 0.95,
            ease: "none",
            duration: 4,
          },
          0
        )

        // Show content
        .fromTo(
          content.current,
          {
            opacity: 0,
            y: 80,
          },
          {
            opacity: 1,
            y: 0,
            duration: 0.8,
          },
          3
        )

        .add(() => floating.resume());
    }, section);

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={section}
      className="relative h-screen overflow-hidden"
    >
      {/* Background */}

      <div
        ref={background}
        className="absolute inset-0"
      >
        <Image
          src="/images/members-bg.jpg"
          alt=""
          fill
          className="object-cover"
        />

        <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/60 to-black/80" />
      </div>

      {/* Hands */}

      <Image
        src="/images/left-hand.png"
        alt=""
        width={450}
        height={450}
        className="absolute left-0 top-1/2 -translate-y-1/2 select-none pointer-events-none"
      />

      <Image
        src="/images/right-hand.png"
        alt=""
        width={450}
        height={450}
        className="absolute right-0 top-1/2 -translate-y-1/2 select-none pointer-events-none"
      />

      {/* Card */}

      <div
        ref={card}
        className="absolute left-[280px] top-[250px] z-20"
      >
        <Image
          src="/card.webp"
          width={210}
          height={135}
          alt="Membership Card"
          className="drop-shadow-[0_25px_40px_rgba(0,0,0,0.35)]"
        />
      </div>

      {/* Content */}

      <div
        ref={content}
        className="absolute inset-0 z-30 flex flex-col items-center justify-end pb-28 text-center text-white px-6"
      >
        <span className="uppercase tracking-[0.35em] text-sky-300">
          Join Today
        </span>

        <h2 className="mt-4 text-5xl md:text-6xl font-bold">
          Become a Member
        </h2>

        <p className="mt-6 max-w-2xl text-lg text-gray-200 leading-8">
          Start your financial journey with YPA Wealth Depot. Save
          confidently, access affordable loans, and invest in your future
          with a trusted SACCO.
        </p>

        <button className="mt-10 rounded-full bg-sky-500 px-8 py-4 text-lg font-semibold transition-all duration-300 hover:bg-sky-600 hover:scale-105">
          Join Us
        </button>
      </div>
    </section>
  );
}